package main

// The usage text of the engine command: one block per subcommand, printed on stderr when the command line is not understood.

import (
	"fmt"
	"io"
)

// usage writes the usage text to w.
func usage(w io.Writer) {
	fmt.Fprintln(w, "Usage:")
	fmt.Fprintln(w, "  engine propagate --registry <path> (--contract-file <path> [--contract-path <str>] | --embedded-contract <name>) [--require-registry]")
	fmt.Fprintln(w, "  engine gate-task (--contract-file <path> | --embedded-contract <name>) [--contract-path <str>]")
	fmt.Fprintln(w, "    while a workflow is bound to the repository, the --contract-file form appends the memory instructions of the bound workflow to every")
	fmt.Fprintln(w, "    sub-agent's prompt (the block of memory plan --instructions), in the same rewrite as the contract; the --embedded-contract form never")
	fmt.Fprintln(w, "    does, so the two installed entries never both rewrite a call for the block; without a binding the answer is unchanged")
	fmt.Fprintln(w, "  engine merge-settings --settings <path> --hook-command <binary-path>")
	fmt.Fprintln(w, "  engine uninstall-hooks --settings <path> --hook-command <binary-path>")
	fmt.Fprintln(w, "  engine merge-codex-hooks --hooks <path> --hook-command <binary-path>")
	fmt.Fprintln(w, "  engine uninstall-codex-hooks --hooks <path> --hook-command <binary-path>")
	fmt.Fprintln(w, "    merge/remove the three owned Codex memory entries: SessionStart (matcher startup|resume|clear|compact), PreToolUse and PostToolUse (only Engram reads and longterm-mem query/get; tool commands pass --source codex). Foreign values stay byte-identical; edited array layout may change.")
	fmt.Fprintln(w, "    atomic write with <path>.bak; identical merge and absent uninstall write nothing. Exit 0 success, 1 usage error, 2 invalid/unwritable file (untouched).")
	fmt.Fprintln(w, "    install-hooks calls merge only when CODEX_HOME (default ~/.codex) already exists; trust each new handler once in the Codex TUI (/hooks, key t). A SessionStart-only install needs two more trusts; existing SessionStart bytes and trust are unchanged. Neither verb edits config.toml or trust state.")
	fmt.Fprintln(w, "  engine status [--only registry] [--cwd <dir>]")
	fmt.Fprintln(w, "    when CODEX_HOME (default ~/.codex) exists, also checks all three Codex memory entries and names missing or drifted events; run install-hooks to repair. Present is not trusted; each new handler needs human trust in the Codex TUI (/hooks, key t). No Codex home means no extra line.")
	fmt.Fprintln(w, "    the doctor of an installation: one line per check, [OK  ], [WARN] or [FAIL]; exit 0 healthy, 1 a check failed, 2 a warning and no failure. --cwd names the directory whose")
	fmt.Fprintln(w, "    .atl/skill-registry.md is looked for (default the working directory). --only registry reports that registry alone, the one line, with the exit code of that check: it is")
	fmt.Fprintln(w, "    how the overlay's doctor judges the registry of a project. A flag takes its value as the next argument or after an equals sign (--cwd=<dir>, --only=registry); the second is how a directory whose name starts with two dashes is given. Any other argument, a flag with no value (or an empty one, or another flag in its place) and an --only that names no check are usage errors: exit 1, not the 2 of a degraded report")
	fmt.Fprintln(w, "  engine runtime <action> [--target claude|opencode|codex|pi|all] [--config-root <path>]")
	fmt.Fprintln(w, "                          [--component runtime-parity|longterm-mem] [--state-dir <path>]")
	fmt.Fprintln(w, "    action: status | install | update | uninstall")
	fmt.Fprintln(w, "    --target: opencode (default), claude, codex, pi, or all (--component runtime-parity only)")
	fmt.Fprintln(w, "    --component: runtime-parity (default, the --target adapters above), or longterm-mem")
	fmt.Fprintln(w, "      (a single component spanning claude+opencode+codex; no update/rollback action)")
	fmt.Fprintln(w, "    --state-dir: registration.json directory for --component longterm-mem (default ~/.labdrian-overlay)")
	fmt.Fprintln(w, "  engine runtime capabilities [--target claude|codex|pi|opencode|all]")
	fmt.Fprintln(w, "    read-only: prints, as JSON, what each runtime adapter declares it supports (default --target all);")
	fmt.Fprintln(w, "    every supported or partial claim names the tests that prove it, every partial or unsupported claim")
	fmt.Fprintln(w, "    states its limit, and untested appears only for a runtime that cannot be exercised on this machine")
	fmt.Fprintln(w, "    reads no configuration, HOME, or file; exit 0 success, 2 unknown --target value, 1 usage error including an unknown flag")
	fmt.Fprintln(w, "  engine runtime probe [--target claude|codex|pi|all]")
	fmt.Fprintln(w, "    read-only: prints, as JSON, whether each selected runtime's credentials file is present (default --target all),")
	fmt.Fprintln(w, "    whether the Engram database, the longterm-mem registration record, and the gentle-ai binary on PATH are present")
	fmt.Fprintln(w, "    (stat only), from the real HOME and PATH, and whether the project's procedural skills lock can be read (the one")
	fmt.Fprintln(w, "    file it reads, through the reader session start uses); it never opens another file and never runs a program, so")
	fmt.Fprintln(w, "    a present credentials file does not prove the runtime is authenticated; exit 0 success, 2 unknown --target value,")
	fmt.Fprintln(w, "    1 usage error including an unknown flag")
	fmt.Fprintln(w, "  OVERLAY_DIR=<repo-root> gentle-ai-overlay gadu-generate [--check]")
	fmt.Fprintln(w, "  engine pipkg build|check --overlay-root <path> --registry <path> --dest-dir <path>")
	fmt.Fprintln(w, "    build: writes the labdrian-pi package tree to --dest-dir, then removes from $HOME/.pi/agent/agents every symlink")
	fmt.Fprintln(w, "    to an agent of --dest-dir that the package no longer ships, and says which; a file, and a symlink to any other")
	fmt.Fprintln(w, "    path, is never touched")
	fmt.Fprintln(w, "    check: reports drift between --dest-dir and the current manifest; exit 1 on drift; changes nothing")
	fmt.Fprintln(w, "  engine manifest routes --overlay-root <dir> --target <name> --skills-root <dir> [--agents-root <dir>] [--manifest <file>] [--managed]")
	fmt.Fprintln(w, "    read-only: tells what the overlay does with each row of overlay.manifest (default <overlay-root>/overlay.manifest) for one target, a row a line in the order")
	fmt.Fprintln(w, "    of the manifest, in five columns separated by a tab: the path of the row; its route (skill, agent, opencode-agent, codex-agent, mcp, non-deployable, or the third column when it is")
	fmt.Fprintln(w, "    none of these, which takes the skill route under its own name); where its file is in the overlay repository; the absolute path the overlay copies it from; and the")
	fmt.Fprintln(w, "    absolute path it is copied to for --target. A column with nothing to say is empty, and an empty column is never followed by one that is not. --managed keeps the rows")
	fmt.Fprintln(w, "    whose second column is managed. The overlay script owns the directories of its targets and hands them over: --skills-root is where --target keeps its skills, and")
	fmt.Fprintln(w, "    --agents-root where it keeps its native agents (needed when the manifest routes an agent to claude, a native agent to opencode, or a Codex agent to codex). A path named twice takes the route")
	fmt.Fprintln(w, "    of the first row that names it. A manifest that is not there has no row, and a warning on stderr says so. exit 0 success; 1 for a usage error, a manifest that is there and")
	fmt.Fprintln(w, "    cannot be read, an unknown --target, or a longterm-mem/ row with no route or an unknown one (said as 'route_resolve: longterm-mem row ...' on stderr): nothing is")
	fmt.Fprintln(w, "    printed on stdout, so a caller never acts on part of a manifest")
	fmt.Fprintln(w, "  engine registry repair-sdd --registry <path> --target <name> --skills-root <dir>")
	fmt.Fprintln(w, "    writes the rows of the SDD executor skills (sdd-apply, sdd-archive, ..., sdd-verify) into the skill registry at --registry, with the scope executor, one for each that is")
	fmt.Fprintln(w, "    installed in --skills-root (<dir>/<name>/SKILL.md; --target only names the target in what it says), which gentle-ai leaves out of the registry it generates. The note")
	fmt.Fprintln(w, "    and the rows of an earlier repair are replaced; every other line stays. A project with no registry gets one. It takes the lock `propagate` takes (<registry>.lock, waiting up")
	fmt.Fprintln(w, "    to 2 seconds) and writes the registry whole through a temporary file and a rename (mode 0644). It says each executor that is not installed on stderr (WARN: ...) and")
	fmt.Fprintln(w, "    sums up on stdout (repair-sdd-registry: registry=... target=... sdd_executors=N missing=M). exit 0 success; 1 for a usage error, a registry without the headings")
	fmt.Fprintln(w, "    '## Skills' and '## Loading protocol' (ERROR: registry has no '...' section: <path>), a lock that stays taken, or a file that cannot be read or written: the registry is as it was")
	fmt.Fprintln(w, "  engine installed-targets record|release --state-dir <dir> --target <name>")
	fmt.Fprintln(w, "  engine installed-targets list --state-dir <dir>")
	fmt.Fprintln(w, "  engine installed-targets assess --state-dir <dir> [--purge] [--unregister-failed]")
	fmt.Fprintln(w, "  engine installed-targets retire --state-dir <dir> --binary <path> [--purge]")
	fmt.Fprintln(w, "    the record of the runtimes the overlay has installed longterm-mem for: the file <dir>/longterm-mem/installed-targets, one name a line, and the only thing that says whether a runtime still")
	fmt.Fprintln(w, "    depends on the shared binary. record adds --target to it, once, after longterm-mem registered it (a name this build cannot install for is refused); release takes it out, rewriting")
	fmt.Fprintln(w, "    the record from the names it vouches for (garbage is compacted away, a name only a newer build knows stays; the last name leaves an empty record, not none). A name is a bare word of")
	fmt.Fprintln(w, "    at most 64 bytes; a NUL byte, a blank or padded line, a carriage return and a line the file ends in the middle of are not names. A record that is there and cannot be read is never")
	fmt.Fprintln(w, "    appended to or rewritten. list prints the names, one a line. assess says what an uninstall comes to once its targets are dealt with, from the record as it is: exit 0 and nothing said")
	fmt.Fprintln(w, "    when the registration record and the shared binary may go (the record is there and holds nothing, or --purge), exit 3 and the reason when they are kept (an unregister failed, the record")
	fmt.Fprintln(w, "    cannot be read, there is no record, or a target is still installed: the names are printed). --unregister-failed says that a target was not unregistered. retire removes the binary at")
	fmt.Fprintln(w, "    --binary, the path the overlay deployed it to and wrote into every runtime's entry (the engine does not derive it), and then the record, when the record read again under the lock")
	fmt.Fprintln(w, "    says that nothing depends on the binary or --purge forces it, and says which (==> longterm-mem binary removed|already absent: <path>). Every read-modify-write takes the lock")
	fmt.Fprintln(w, "    <dir>/.installed-targets.flock (an advisory file lock, waiting up to 2 seconds; the kernel lets it go when the process ends), so two overlay commands take turns. The words are the")
	fmt.Fprintln(w, "    script's: ERROR: longterm-mem: ..., WARN: longterm-mem: ... Exit 0 on success; 1 for a usage error (including an unknown flag), a lock that stays taken, or a file that cannot be read or")
	fmt.Fprintln(w, "    written, with the record as it was; 3 from assess when the registration record and the binary are kept")
	fmt.Fprintln(w, "  engine skills <verb>   (verbs: list, status, candidates, validate, install, adopt, uninstall, add, remove, sync-manifest, lint, approve, project-register, project-revise, project-status, project-retire)")
	fmt.Fprintln(w, "    list          [--registry <path>]                                                      print sorted registry entries")
	fmt.Fprintln(w, "    status        [--registry <path>]                                                      print count summary (total/core/custom)")
	fmt.Fprintln(w, "    validate      [--registry <path>] [--manifest <path>] --source-root <path>              cross-check registry vs manifest and skills/ on disk; exit 1 on divergence")
	fmt.Fprintln(w, "    install       [--registry <path>] [--source-root <path>] [--project-id <id>]           install project-scoped skills into <cwd>/.claude/skills/ and <cwd>/.agents/skills/, replacing only what it installed and left unmodified")
	fmt.Fprintln(w, "                  install records each file it writes (with its SHA-256) in the project lock. It refuses, naming the path, a hand-edited file or a directory it did not install,")
	fmt.Fprintln(w, "                  reports every refusal, and then writes nothing for any skill. A second install with no source change prints \"unchanged: <id>\" and writes nothing.")
	fmt.Fprintln(w, "    adopt         [--registry <path>] [--source-root <path>] [--project-id <id>]           record skill directories already in the project as installed, only when they are exactly the current source;")
	fmt.Fprintln(w, "                  nothing is adopted silently: a directory stays foreign to install until skills adopt records it. adopt writes the project lock and no skill file")
	fmt.Fprintln(w, "    uninstall     [--dry-run] <id>                                                         remove from <cwd> a skill install put there: every file its install record lists, in both runtimes,")
	fmt.Fprintln(w, "                  then the record (the lock file stays). It refuses, naming the path, a hand-edited file, an id with no install record, or a procedural skill")
	fmt.Fprintln(w, "                  (project-retire's), and then removes nothing; a file the record does not list is left, with its directory (note: kept <dir>). No registry is read")
	fmt.Fprintln(w, "    add           <id> [--registry <path>] [--manifest <path>] [--source-root <path>] [--repo <url>] [--ref <sha>]  register a skill")
	fmt.Fprintln(w, "    remove        <id> [--registry <path>] [--manifest <path>]                             unregister a skill from registry and manifest")
	fmt.Fprintln(w, "    sync-manifest [--registry <path>] [--manifest <path>]                                  regenerate */SKILL.md rows from registry")
	fmt.Fprintln(w, "    lint          <path> | --rules                                                         lint a SKILL.md file, or print the rule table; exit 1 on any hard error")
	fmt.Fprintln(w, "    approve       --id <id> --approver <label> --source-root <path>                        record a human approval of skills/<id>/SKILL.md, bound to the digest of its exact bytes")
	fmt.Fprintln(w, "                  a skill that fails the hard lint is refused, except a baseline skill (a grandfathered global skill, which predates the lint budget and will be rewritten in a later feature):")
	fmt.Fprintln(w, "                  for those, a size or description finding is printed as a \"warning:\" line on stderr, the approval is still recorded, and the exit is 0;")
	fmt.Fprintln(w, "                  any other hard finding, such as a missing front matter, refuses a baseline skill too")
	fmt.Fprintln(w, "    project-register --project-root <abs> --candidate <key> [--dry-run] [--registry <path>] <draft-file>")
	fmt.Fprintln(w, "                                                                                           register a project-tier procedural skill; --dry-run prints the plan and writes nothing")
	fmt.Fprintln(w, "    project-revise   --project-root <abs> --candidate <key> [--dry-run] [--registry <path>] <draft-file>")
	fmt.Fprintln(w, "                                                                                           revise an agent-owned project skill; --dry-run prints the plan and writes nothing")
	fmt.Fprintln(w, "    project-status   --project-root <abs> [--registry <path>] [<id>]")
	fmt.Fprintln(w, "                                                                                           report project-tier ownership and global supersession")
	fmt.Fprintln(w, "    project-retire   --project-root <abs> [--dry-run] [--reason <reason>] [--absorbed-into <id>] [--registry <path>] <id>")
	fmt.Fprintln(w, "                                                                                           retire an agent-owned project skill; --dry-run prints the removal plan")
	fmt.Fprintln(w, "    candidates       [--project-root <abs>] [--status <status>]... [--kind <kind>] [--drafts] [--json]")
	fmt.Fprintln(w, "                                                                                           read-only Engram candidate and draft listing with reconciliation anomalies; source failures exit 2")
	fmt.Fprintln(w, "    locking: add, remove, sync-manifest and approve hold an exclusive lock, and validate and install a shared one, on .skills.registry.yaml.lock beside the registry")
	fmt.Fprintln(w, "    (created by the first write, never removed, git-ignored; shared holders never create it). A lock taken for 2 seconds means another skills command is in progress:")
	fmt.Fprintln(w, "    the verb changes nothing and reports it with exit 2 (retry); exit 1 is unchanged (the verb ran or was refused, or the lock could not be created)")
	fmt.Fprintln(w, "    project lock: project-register, project-revise, project-retire, install, adopt and uninstall also take an exclusive lock on the project root directory itself (--project-root, or")
	fmt.Fprintln(w, "    the working directory for install, adopt and uninstall), so no file is created in the project; a busy one is exit 2 too, and a filesystem that cannot lock a directory refuses the verb (exit 1).")
	fmt.Fprintln(w, "    A verb that holds both takes the overlay lock first, then the project lock, so install and adopt can wait up to twice the lock bound (2 seconds each) when both are busy;")
	fmt.Fprintln(w, "    project-status takes a shared lock on the project. A writer refuses, with nothing locked, when the registry it would lock does not exist")
	fmt.Fprintln(w, "  engine skills guard-hook")
	fmt.Fprintln(w, "    internal Claude Code PreToolUse hook command (install-hooks installs it; on an existing install, re-run install-hooks and restart Claude Code to load it):")
	fmt.Fprintln(w, "    reads the hook JSON on stdin and denies the agent running 'skills approve' (approval is a human step) or writing a skill's .approval.json record with")
	fmt.Fprintln(w, "    Write, Edit, MultiEdit, or NotebookEdit. A denial is {\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"deny\",")
	fmt.Fprintln(w, "    \"permissionDecisionReason\":...}} with exit 0; an allow prints nothing. A speed bump, not a security boundary: it matches the command text and the file name,")
	fmt.Fprintln(w, "    so it can be bypassed and can deny text that only spells the invocation. It never blocks on an error (unusable input is an allow): exit 0 always, 1 usage error")
	fmt.Fprintln(w, "  engine sync-trigger --event session-end|archive --cwd <path> [--state-dir <path>]")
	fmt.Fprintln(w, "    always exits 0 to its caller; detaches a bounded longterm-mem sync and logs its outcome")
	fmt.Fprintln(w, "    to <state-dir>/logs/sync-trigger.log (owner-only, 0600); a log that reached 1 MiB is moved to")
	fmt.Fprintln(w, "    sync-trigger.log.1 when it is next opened, keeping three older files (.1 to .3); a state dir")
	fmt.Fprintln(w, "    that is not absolute (HOME unset and no --state-dir) is refused and nothing is written")
	fmt.Fprintln(w, "  engine review-receipt capture --cwd <repo> [--change <name> | --feature <name>]")
	fmt.Fprintln(w, "    persists every surviving approved review receipt to openspec/changes/<change>/review-receipts/")
	fmt.Fprintln(w, "    --change resolves ambiguity when more than one active change exists; omit it to auto-detect")
	fmt.Fprintln(w, "    --feature persists them to odd/review-receipts/<feature>/ instead, beside odd/tasks/<feature>.md,")
	fmt.Fprintln(w, "    for an ODD review that belongs to no change; --change and --feature cannot be given together")
	fmt.Fprintln(w, "  engine review-receipt hook --cwd <repo>")
	fmt.Fprintln(w, "    fail-closed PreToolUse Bash hook: reads tool_input JSON from stdin, captures before")
	fmt.Fprintln(w, "    'gentle-ai review acknowledge-approved', denies (exit 2) on ambiguity or capture failure;")
	fmt.Fprintln(w, "    with several active changes it allows once every approved receipt is persisted byte for byte")
	fmt.Fprintln(w, "    under one of them or in a feature folder (capture --change <name> or --feature <name>)")
	fmt.Fprintln(w, "  engine shaper assess --root <abs> --handoff <rel> --goal <rel> [--view]")
	fmt.Fprintln(w, "    read-only readiness assessment; exit 0 ready, 3 draft, 2 invalid, 1 usage or internal error")
	fmt.Fprintln(w, "    --view prints exactly the rendered clearance view bytes the Pi dialog displays")
	fmt.Fprintln(w, "  engine shaper clearance record --root <abs> --handoff <rel> --goal <rel> --stdin")
	fmt.Fprintln(w, "    stores a human clearance decision read only from stdin after re-deriving and checking its binding")
	fmt.Fprintln(w, "    not a signature: any process running as the same OS user, including any installed Pi extension, can forge one")
	fmt.Fprintln(w, "  engine shaper guard-hook")
	fmt.Fprintln(w, "    Claude Code PreToolUse deny guard for clearance recording and the clearance store (exit 2 denies; a speed bump)")
	fmt.Fprintln(w, "  engine memory plan --profile <name> [--goal <path>] [--goal-directive <path>] [--handoff-directive <path>]")
	fmt.Fprintln(w, "    read-only: resolves a workflow profile's default memory directive, narrows it with an optional")
	fmt.Fprintln(w, "    Goal-supplied then handoff-supplied directive, and prints the resulting query plan as JSON")
	fmt.Fprintln(w, "    exit 0 plan resolved, 2 refused/invalid input, 1 usage or output error; it never queries or writes memory")
	fmt.Fprintln(w, "  engine memory plan --project <id> --workflow <id>")
	fmt.Fprintln(w, "    read-only: prints the plan the memory gate applies to the workflow, from its log alone: the profile's ceiling")
	fmt.Fprintln(w, "    narrowed by the Goal's directive, the shaper handoff's, then the latest role handoff's (a log of version 1 or 2")
	fmt.Fprintln(w, "    holds none, so its plan is the ceiling); it does not combine with --profile, --goal, --goal-directive or")
	fmt.Fprintln(w, "    --handoff-directive (exit 1); exit 2 for a workflow that is not owned or a plan that cannot be computed")
	fmt.Fprintln(w, "  engine memory plan --instructions [--project <id> --workflow <id>]")
	fmt.Fprintln(w, "    read-only: prints that plan as the memory instructions an agent follows (the block SessionStart and gate-task give):")
	fmt.Fprintln(w, "    the sources to read, the project each is read with, the goal under scope goal, that writes are not limited, and the")
	fmt.Fprintln(w, "    T1/T2 procedural contract; under scope none it says to read no memory. Without --project and --workflow it reads the")
	fmt.Fprintln(w, "    binding of the working directory's repository; when no workflow is bound it says so and exits 0. exit 2 for a binding or")
	fmt.Fprintln(w, "    workflow that cannot be followed or a closed one; it does not combine with the --profile form (exit 1)")
	fmt.Fprintln(w, "  engine workflow create --project <id> --workflow <id> --goal <path> --profile <name> [--role-chain <id>] [--handoff <path>]")
	fmt.Fprintln(w, "  engine workflow start|pause|resume|status|narrow --project <id> --workflow <id>")
	fmt.Fprintln(w, "  engine workflow stage  --project <id> --workflow <id> --stage <name>")
	fmt.Fprintln(w, "  engine workflow verify --project <id> --workflow <id> --goal <path>")
	fmt.Fprintln(w, "  engine workflow close  --project <id> --workflow <id> --outcome completed|abandoned [--reason <text>]")
	fmt.Fprintln(w, "    Phase 6 standalone workflow lifecycle: local bookkeeping under $XDG_STATE_HOME/labdrian/workflows/;")
	fmt.Fprintln(w, "    no verb requires Gentle AI, gentle-pi, a runtime, memory, or auth (an unavailable dependency is")
	fmt.Fprintln(w, "    recorded on the event, and a dependency is recorded available only when its file or binary is seen by stat,")
	fmt.Fprintln(w, "    never opened, run, or trusted). --goal is re-read from disk at both create and verify;")
	fmt.Fprintln(w, "    no path is ever persisted. create refuses a Goal whose project_id is not --project, and records the")
	fmt.Fprintln(w, "    project's shared identity for the memory gate, the first of: the .longterm-mem-project file at the")
	fmt.Fprintln(w, "    main checkout's root, the origin remote, the main checkout's directory name, and outside git the")
	fmt.Fprintln(w, "    working directory's name; when none can be read it records --project and warns.")
	fmt.Fprintln(w, "    create records the memory narrowers: the directive of a Goal v3, the digest and directive of the shaper")
	fmt.Fprintln(w, "    handoff v4 read from --handoff (another version, or one of another project or goal, is refused), and the")
	fmt.Fprintln(w, "    directive of the role chain's head record. narrow appends a narrowed event for the role handoff the bound")
	fmt.Fprintln(w, "    chain received since the log last recorded its head; the latest role directive applies over the base")
	fmt.Fprintln(w, "    (ceiling, Goal, shaper handoff). create and narrow refuse a directive that widens the plan, naming it,")
	fmt.Fprintln(w, "    and write nothing; narrow refuses a workflow created before narrowers (create it again).")
	fmt.Fprintln(w, "    exit 0 success, 2 refused/invalid (illegal transition,")
	fmt.Fprintln(w, "    verify failure, non-owned state, a Goal of another project, a refused handoff or narrower), 1 usage error")
	fmt.Fprintln(w, "  engine workflow bind --project <id> --workflow <id>")
	fmt.Fprintln(w, "  engine workflow unbind")
	fmt.Fprintln(w, "  engine workflow binding")
	fmt.Fprintln(w, "    Phase 7 session binding: records which workflow the git repository containing the working directory")
	fmt.Fprintln(w, "    follows, in $XDG_STATE_HOME/labdrian/bindings/<repo-key>.json. The key is the SHA-256 of the git common directory,")
	fmt.Fprintln(w, "    so every worktree of a repository shares one binding. bind needs an existing, owned, not closed workflow;")
	fmt.Fprintln(w, "    it refuses to replace a binding to a workflow that is still active or whose log cannot be read (unbind first)")
	fmt.Fprintln(w, "    and replaces a stale one (closed, gone, corrupt, or not ours). unbind is idempotent and prints {\"removed\": true|false}. binding is read-only:")
	fmt.Fprintln(w, "    it prints the binding's classification and, when owned, the bound workflow's classification and status.")
	fmt.Fprintln(w, "    exit 0 success, 2 refused/invalid (no git repository, a workflow that cannot be bound, a binding file that is not ours")
	fmt.Fprintln(w, "    or cannot be used (foreign, malformed, unavailable), another bind or unbind in progress (busy), a binding another")
	fmt.Fprintln(w, "    process changed meanwhile), 1 usage error")
	fmt.Fprintln(w, "  engine projection hook --event UserPromptSubmit|PreToolUse|SessionStart|PostToolUse [--source claude|codex]")
	fmt.Fprintln(w, "    --source names the runtime that sent the hook (default: claude, which is the behavior of every entry install-hooks wrote before). codex adapts the tool names Codex sends for a PreToolUse or PostToolUse call (mcp__longterm_mem__query and mcp__longterm_mem__get become the names the gate knows) before the gate or the evidence sees them; every other name, the input and the output are unchanged. Any other value is a usage error (exit 1) and nothing is read.")
	fmt.Fprintln(w, "    internal Claude Code hook command (install-hooks installs it; on an existing install, re-run install-hooks and restart Claude Code to load it): reads the hook JSON on stdin and prints at most one JSON object.")
	fmt.Fprintln(w, "    UserPromptSubmit prints {\"hookSpecificOutput\":{\"hookEventName\":\"UserPromptSubmit\",\"additionalContext\":...},\"systemMessage\":...}, which puts the")
	fmt.Fprintln(w, "    workflow the repository is bound to (see workflow bind) into the session: id, profile, status, stages, and the memory plan;")
	fmt.Fprintln(w, "    the binding to a closed workflow is removed, and the note says whether it was removed, left alone, or the removal failed.")
	fmt.Fprintln(w, "    PreToolUse gates a tool call against the bound workflow and never writes: it denies Write, Edit, MultiEdit, and NotebookEdit while the")
	fmt.Fprintln(w, "    workflow is paused (never Bash, never a read). For a memory read (a longterm-mem query or get; an Engram mem_search, mem_context,")
	fmt.Fprintln(w, "    mem_get_observation or mem_timeline) it denies every read when the memory plan has no project, a read of a source the plan excludes,")
	fmt.Fprintln(w, "    a longterm-mem query whose project differs from the plan's project or, under scope goal, whose goal is missing or differs from")
	fmt.Fprintln(w, "    the plan's goal, and an Engram mem_search or mem_context that names another")
	fmt.Fprintln(w, "    project than the one Engram knows the workflow's identity by, names none, or sets all_projects; a read by id passes once its")
	fmt.Fprintln(w, "    source is in the plan. The project's procedural skills (.labdrian/procedural-skills.lock.json) are of source procedural-skills:")
	fmt.Fprintln(w, "    the Skill tool for a procedural skill of the lock, and a Read of its SKILL.md, are denied when the plan excludes that source;")
	fmt.Fprintln(w, "    every other skill and every other Read pass, no lock means no procedural skill, and a lock it cannot read gives one warning.")
	fmt.Fprintln(w, "    It never touches promote, an Engram write, or any write. A denial is")
	fmt.Fprintln(w, "    {\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"deny\",\"permissionDecisionReason\":...}} with exit 0; an allow prints")
	fmt.Fprintln(w, "    nothing (or only a systemMessage warning) and never permissionDecision allow.")
	fmt.Fprintln(w, "    SessionStart prints {\"hookSpecificOutput\":{\"hookEventName\":\"SessionStart\",\"additionalContext\":...}}, the memory instructions of the")
	fmt.Fprintln(w, "    bound workflow (see memory plan --instructions), and is silent whenever there is no block to give; it never writes.")
	fmt.Fprintln(w, "    It also asks, within three seconds, which sources of the plan can be read, and adds a line \"Do not read <source>: it is unavailable")
	fmt.Fprintln(w, "    in this session (<reason>).\" for each that cannot (engram: 'engram stats'; longterm-mem: its binary and an MCP entry in any runtime;")
	fmt.Fprintln(w, "    procedural-skills: the project's lock); the line only informs, and the gate is unchanged.")
	fmt.Fprintln(w, "    PostToolUse records the evidence of a memory read that ran (the reads PreToolUse checks) while an open workflow is bound: one")
	fmt.Fprintln(w, "    line in <state home>/labdrian/workflows/<project>/<workflow>.memory.jsonl with the tool, the source, what the call named, and")
	fmt.Fprintln(w, "    the SHA-256 and length of tool_response, never the response; its input may be up to 64 MiB. It is silent, or, when the line")
	fmt.Fprintln(w, "    cannot be written, prints {\"hookSpecificOutput\":{\"hookEventName\":\"PostToolUse\",\"additionalContext\":...}} saying so.")
	fmt.Fprintln(w, "    silent (no output at all) when the repository is not bound, the input is not a usable hook input, or the directory is not in a")
	fmt.Fprintln(w, "    repository; on UserPromptSubmit a bound workflow that cannot be followed, or a binding store that cannot be read, gives one warning and")
	fmt.Fprintln(w, "    nothing is projected (PreToolUse allows quietly). read-only otherwise, but for the evidence PostToolUse appends. exit 0 always (it never blocks a prompt or a tool call), 1 usage error")
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "Embedded contracts: anti-generic-design")
	fmt.Fprintln(w, "status exit codes: 0 ok, 1 hard failure, 2 degraded")
}
